grade.command_excerpt:
Get-Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $c = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round(($c | Where-Object Path -Like '*\available mbytes').CookedValue / 1024, 2)
        CommitGiB = [math]::Round(($c | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB, 2)
        CPUPercent = [math]::Round(($c | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize

$rows = @(Get-Counter -Counter '\Processor(_Total)\% Processor Time',
  '\System\Processor Queue Length','\Memory\Available MBytes',
  '\Memory\Committed Bytes','\Memory\Pool Nonpaged Bytes',
  '\Memory\Pool Paged Bytes' -SampleInterval 5 -MaxSamples 4 -ErrorAction Stop |
  ForEach-Object {
    $v = @{}
    foreach ($counter in $_.CounterSamples) {
      $v[($counter.Path -split '\\')[-1]] = $counter.CookedValue
    }
    [pscustomobject]@{
      Time = $_.Timestamp
      CPU = [math]::Round($v['% processor time'], 1)
      Queue = $v['processor queue length']
      FreeMiB = $v['available mbytes']
      Commit = $v['committed bytes']
      Nonpaged = $v['pool nonpaged bytes']
      Paged = $v['pool paged bytes']
    }
  })
$rows | Format-Table Time,CPU,Queue,FreeMiB -AutoSize
$first = $rows[0]
$last = $rows[-1]
if (($rows.CPU | Measure-Object -Minimum).Minimum -ge 90) {
  'CPU: sustained high CPU during this sample.'
} else {
  'CPU: no sustained high CPU during this sample.'
}
$growth = @('Commit','Nonpaged','Paged' | Where-Object {
  ($last.$_ - $first.$_) -ge 256MB
})
if ($growth.Count) {
  "RAM: $($growth -join ', ') grew by at least 256 MiB. Repeat after CI drains to see whether growth persists at idle."
} else {
  'RAM: no rapid growth in commit or kernel pools during this sample.'
}
if ($last.FreeMiB -lt 2048) { 'Action: hold new CI jobs until free RAM recovers.' }

Get-Counter -Counter '\Processor(_Total)\% Processor Time','\System\Processor Queue Length','\Memory\Available MBytes','\Memory\Committed Bytes','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes' -SampleInterval 5 -MaxSamples 3 |
  ForEach-Object {
    $_.Timestamp
    $_.CounterSamples | Format-Table Path,CookedValue -AutoSize
  }

$samples = @(Get-Counter -Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $c = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($c | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($c | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPct = [math]::Round(($c | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
})
$samples | Format-Table -AutoSize
if ($samples.Count -lt 2) { throw 'Need at least two readings to compare.' }
if ($samples[-1].CommitGiB -gt $samples[0].CommitGiB -and $samples[-1].FreeGiB -lt $samples[0].FreeGiB) {
    'RAM: pressure rose during this sample. Check whether it persists after CI goes idle.'
} else {
    'RAM: this sample does not show rising commit with falling free RAM.'
}
if (($samples | Measure-Object -Property CPUPct -Minimum).Minimum -ge 90) {
    'CPU: at least 90% throughout this sample. If CI is idle, identify the busy process.'
} else {
    'CPU: below 90% for at least part of this sample.'
}
